<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
const route = useRoute()
import { ElMessage } from 'element-plus'
import { createTeacherTask, getClasses, getCourses, getReadyCaseVersions, getTeacherTasks } from '@/api/teacher'
import type { CreateTeacherTask, ReadyCaseVersion, TeacherTask, TeachingClass } from '@/types/teacher'
import { displayTime } from '@/utils/student'
const tasks=ref<TeacherTask[]>([]),classes=ref<TeachingClass[]>([]),versions=ref<ReadyCaseVersion[]>([]),drawer=ref(false),loading=ref(false),creating=ref(false);const form=ref<CreateTeacherTask>({classId:'',title:'',instructions:'',caseVersionId:'',startAt:null,dueAt:null,allowLate:false,reportTemplate:{}})
async function load(){loading.value=true;try{const [taskData,courseData,versionData]=await Promise.all([getTeacherTasks(),getCourses(),getReadyCaseVersions()]);tasks.value=taskData;versions.value=versionData;classes.value=(await Promise.all(courseData.map(course=>getClasses(course.id)))).flat()}catch(e){ElMessage.error(e instanceof Error?e.message:'任务数据加载失败')}finally{loading.value=false}}
async function create(){if(creating.value)return;if(!form.value.classId||!form.value.title.trim()||!form.value.caseVersionId){ElMessage.warning('请填写任务名称并选择班级、已发布教学版本');document.getElementById(!form.value.title.trim()?'task-name':!form.value.classId?'task-class':'task-version')?.focus();return}if(form.value.startAt&&form.value.dueAt&&new Date(form.value.dueAt)<new Date(form.value.startAt)){ElMessage.warning('截止时间不能早于开始时间');return}creating.value=true;try{await createTeacherTask(form.value);drawer.value=false;form.value={classId:'',title:'',instructions:'',caseVersionId:'',startAt:null,dueAt:null,allowLate:false,reportTemplate:{}};await load();ElMessage.success('任务已创建')}catch(e){ElMessage.error(e instanceof Error?e.message:'任务创建失败')}finally{creating.value=false}}
onMounted(() => { drawer.value = route.query.create === '1'; void load() })
</script>
<template><main class="page"><div class="head"><div><p>教师 / 教学管理</p><h1>实训任务</h1></div><div><el-button @click="$router.push('/teacher/courses')">课程班级</el-button><el-button type="primary" @click="drawer=true">创建任务</el-button></div></div><el-card><el-table :data="tasks" v-loading="loading"><el-table-column prop="title" label="任务标题" min-width="180"/><el-table-column prop="className" label="班级"/><el-table-column prop="caseName" label="案例" min-width="150"/><el-table-column label="时间" min-width="230"><template #default="{row}">{{displayTime(row.startAt)}}<br>截止：{{displayTime(row.dueAt)}}</template></el-table-column><el-table-column label="分配/提交" width="110"><template #default="{row}">{{row.assignedCount}} / {{row.submittedCount}}</template></el-table-column><el-table-column label="操作" width="110"><template #default="{row}"><el-button link type="primary" @click="$router.push(`/teacher/tasks/${row.id}/submissions`)">查看提交</el-button></template></el-table-column></el-table></el-card><el-drawer v-model="drawer" title="创建实训任务" size="min(480px, 100vw)" :close-on-press-escape="!creating" :close-on-click-modal="!creating" :show-close="!creating"><el-form label-position="top" :disabled="creating"><section><h3>基本信息</h3><el-form-item label="任务名称" required><el-input id="task-name" v-model="form.title"/></el-form-item><el-form-item label="任务说明"><el-input v-model="form.instructions" type="textarea"/></el-form-item></section><section><h3>教学对象</h3><el-form-item label="班级" required><el-select id="task-class" v-model="form.classId"><el-option v-for="item in classes" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item></section><section><h3>教学案例</h3><el-form-item label="已发布教学版本" required><el-select id="task-version" v-model="form.caseVersionId"><el-option v-for="item in versions" :key="item.id" :label="`${item.caseName}（${item.internalCode}）`" :value="item.id"/></el-select></el-form-item></section><section><h3>时间与规则</h3><el-form-item label="开始时间"><el-date-picker v-model="form.startAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-form-item label="截止时间"><el-date-picker v-model="form.dueAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-checkbox v-model="form.allowLate">允许迟交</el-checkbox></section></el-form><template #footer><el-button :disabled="creating" @click="drawer=false">取消</el-button><el-button type="primary" :loading="creating" :disabled="creating" @click="create">创建任务</el-button></template></el-drawer></main></template>
<style scoped>.page{max-width:1440px;min-height:100vh;margin:auto;padding:36px 32px}.head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:24px}.head>div:last-child{display:flex;flex-wrap:wrap;gap:10px}.head p{margin:0;color:#64748b;font-size:13px}h1{margin:7px 0;color:#142d4d}.el-select,.el-date-editor{width:100%}:deep(.el-table .cell){white-space:normal}@media(max-width:720px){.page{padding:24px 16px}.head{align-items:flex-start;flex-direction:column}}section{padding-bottom:16px;border-bottom:1px solid #0001}section h3{margin:22px 0 12px}</style>
